CREATE OR REPLACE FUNCTION gx_n1 RETURN NUMBER IS
  v NUMBER := 2.5;
BEGIN
  RETURN v * 2;
END;
/
CREATE OR REPLACE FUNCTION gx_n2(p NUMBER) RETURN NUMBER IS
BEGIN
  RETURN p / 4;
END;
/
CREATE OR REPLACE FUNCTION gx_f1 RETURN VARCHAR2 IS
  a NUMBER(10,2) := 0.1;
  b NUMBER(10,2) := 0.2;
BEGIN
  IF a + b = 0.3 THEN RETURN 'equal'; END IF;
  RETURN 'not equal';
END;
/
CREATE OR REPLACE FUNCTION gx_f2 RETURN VARCHAR2 IS
  t NUMBER(12,2);
BEGIN
  SELECT SUM(amount) INTO t FROM gx_pay;
  RETURN TO_CHAR(t);
END;
/
CREATE OR REPLACE FUNCTION gx_d1(n NUMBER) RETURN VARCHAR2 IS
  b NUMBER(9,0) := n;
  e BINARY_INTEGER := n;
BEGIN
  RETURN (7 / 2) || '|' || ROUND(b / 2) || '|' || (e / 2);
END;
/
CREATE OR REPLACE FUNCTION gx_s1(p VARCHAR2) RETURN VARCHAR2 IS
BEGIN
  RETURN SUBSTR(p, 0, 3) || '|' || SUBSTR(p, -3) || '|' || SUBSTR(p, -3, 2) || '|' || SUBSTR(p, 0) || '|' || SUBSTR(p, 2, 2);
END;
/
